package org.example.backend.controller;
import org.example.backend.service.*;
import org.example.backend.entity.*;
import org.example.backend.result.Result;
import org.example.backend.security.JwtAuthenticationFilter;
import org.junit.jupiter.api.Test;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.http.MediaType;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class TransportEndpointBehaviorTest {
    @Test void avatarProxyPreservesBytesCachePolicyAndFallsBackForUnknownContentType() throws Exception{AliyunOssService service=mock(AliyunOssService.class);var mvc=MockMvcBuilders.standaloneSetup(new FileUploadController(service)).build();byte[] bytes={1,2,3};when(service.downloadAvatar("avatars/a.png")).thenReturn(new AliyunOssService.AvatarObject(bytes,"image/png"));mvc.perform(get("/files/avatar-proxy").param("objectKey","avatars/a.png")).andExpect(content().bytes(bytes)).andExpect(content().contentType(MediaType.IMAGE_PNG)).andExpect(header().string("Cache-Control","max-age=604800, public"));when(service.downloadAvatar("avatars/b")).thenReturn(new AliyunOssService.AvatarObject(bytes,"invalid"));mvc.perform(get("/files/avatar-proxy").param("objectKey","avatars/b")).andExpect(content().contentType(MediaType.APPLICATION_OCTET_STREAM));when(service.uploadAvatar(any())).thenReturn(Map.of("objectKey","avatars/a.png"));mvc.perform(multipart("/files/avatars").file(new MockMultipartFile("file","avatar.png","image/png",bytes))).andExpect(jsonPath("$.data.objectKey").value("avatars/a.png"));}
    @Test void conversationEndpointsUseAuthenticatedIdentityAndEmptyBatchDefaults() throws Exception{AiConversationService service=mock(AiConversationService.class);var mvc=MockMvcBuilders.standaloneSetup(new AiConversationController(service)).build();when(service.listConversations(7)).thenReturn(List.of(Map.of("id","chat")));mvc.perform(get("/ai-assistant/conversations").requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7)).andExpect(jsonPath("$.data[0].id").value("chat"));mvc.perform(put("/ai-assistant/conversations").requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7)).andExpect(status().isOk());mvc.perform(put("/ai-assistant/conversations").requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7).contentType(MediaType.APPLICATION_JSON).content("{\"conversations\":[{\"id\":\"chat\"}]}" )).andExpect(status().isOk());mvc.perform(delete("/ai-assistant/conversations/chat").requestAttr(JwtAuthenticationFilter.AUTH_USER_ID_ATTRIBUTE,7)).andExpect(status().isOk());verify(service).saveConversations(7,List.of());verify(service).saveConversations(7,List.of(Map.of("id","chat")));verify(service).deleteConversation(7,"chat");}
    @Test void runtimeEndpointsForwardQueryMapsAndDefaultMissingReports() throws Exception{DeviceStatusService service=mock(DeviceStatusService.class);var controller=new DeviceStatusController(service);var mvc=MockMvcBuilders.standaloneSetup(controller).build();mvc.perform(get("/device-status/labs/7").param("status","online")).andExpect(status().isOk());mvc.perform(get("/device-status/devices/8")).andExpect(status().isOk());mvc.perform(get("/device-status/events").param("limit","5")).andExpect(status().isOk());mvc.perform(get("/device-status/summary")).andExpect(status().isOk());mvc.perform(post("/device-status/report")).andExpect(status().isOk());mvc.perform(post("/device-status/report").contentType(MediaType.APPLICATION_JSON).content("{\"deviceId\":8}")).andExpect(status().isOk());verify(service).listLabRuntimeStatus(7L,Map.of("status","online"));verify(service).getDeviceRuntimeStatus(8L);verify(service).listEvents(Map.of("limit","5"));verify(service).reportRuntimeStatus(Map.of());verify(service).reportRuntimeStatus(Map.of("deviceId",8));controller.getSummary(null);verify(service,times(2)).getSummary(Map.of());}
    @Test void softwareCrudReturnsServiceResponseWithoutWrappingItAgain() throws Exception{softwareService service=mock(softwareService.class);softwareController controller=new softwareController();ReflectionTestUtils.setField(controller,"softwareService",service);var mvc=MockMvcBuilders.standaloneSetup(controller).build();when(service.getLabSoftware()).thenReturn(Result.success(List.of(Map.of("id",1))));when(service.InserterLabSoftware(any())).thenReturn(Result.success("created"));when(service.updateLabSoftware(eq(1L),any())).thenReturn(Result.success("updated"));when(service.deleteLabSoftware(1L)).thenReturn(Result.success("deleted"));mvc.perform(get("/lab-software")).andExpect(jsonPath("$.data[0].id").value(1));mvc.perform(post("/lab-software").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isOk());mvc.perform(put("/lab-software/1").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isOk());mvc.perform(delete("/lab-software/1")).andExpect(status().isOk());verify(service).InserterLabSoftware(any());verify(service).updateLabSoftware(eq(1L),any());verify(service).deleteLabSoftware(1L);}
}
